files.content:
.page { color: var(--fg-default); }
.name { display: flex; min-width: 0; flex: 1; align-items: center; gap: 12px; }
.name h1 { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--font-size-body); font-weight: 600; }
.readOnly { border-radius: 4px; padding: 4px 8px; background: var(--surface-raised); color: var(--fg-subtle); font-size: var(--font-size-label); white-space: nowrap; }
.topActions { display: flex; align-items: center; gap: 8px; }
.flow { min-width: 600px; padding: 40px 24px 112px; }
.fields { display: flex; flex-direction: column; gap: 0; }
.fields > div { display: grid; grid-template-columns: 120px minmax(0, 1fr); gap: 16px; padding: 10px 0; border-bottom: 1px solid var(--border-subtle); }
.fields > div:first-child { padding-top: 0; }
.fields > div:last-child { padding-bottom: 0; border-bottom: 0; }
.fields dt { color: var(--fg-subtle); line-height: 20px; }
.fields dd { min-width: 0; color: var(--fg-default); line-height: 20px; overflow-wrap: anywhere; }
.sectionHeading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; color: var(--fg-muted); font-weight: 500; }
.rowList { overflow: hidden; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-floating); }
.summaryRow, .windowRow { display: grid; min-height: 44px; align-items: center; gap: 8px; padding: 8px 12px; border-bottom: 1px solid var(--border-subtle); }
.summaryRow:last-child, .windowRow:last-child { border-bottom: 0; }
.summaryRow { grid-template-columns: 24px minmax(88px, .7fr) minmax(0, 1.6fr); }
.summaryRow strong, .windowRow strong { color: var(--fg-default); font-weight: 500; }
.summaryRow > span:last-child, .windowRow > span { min-width: 0; color: var(--fg-subtle); overflow-wrap: anywhere; }
.logic { display: grid; width: 24px; height: 24px; place-items: center; border: 1px solid var(--border); border-radius: 6px; color: var(--fg-subtle); font-size: var(--font-size-label); }
.windowRow { grid-template-columns: 100px minmax(0, 1fr) minmax(0, 1fr); }
.temporary { margin-top: 16px; border-radius: 8px; padding: 12px; background: var(--surface-raised); color: var(--fg-muted); }
.temporary > div { display: flex; justify-content: space-between; gap: 16px; }
.temporary strong { color: var(--fg-default); font-weight: 500; }
.temporary p { margin-top: 8px; color: var(--fg-subtle); line-height: 20px; }
.temporaryOff { background: var(--surface-raised); color: var(--fg-subtle); }
.result { color: var(--fg-success); line-height: 22px; overflow-wrap: anywhere; }
.help { margin-top: 8px; color: var(--fg-subtle); line-height: 20px; }
.infoPanel { display: flex; width: 360px; min-height: 0; flex-shrink: 0; flex-direction: column; overflow: hidden; border: 1px solid var(--border); border-radius: 12px; background: var(--surface-floating); }
.infoHeader { display: flex; min-height: 48px; flex-shrink: 0; align-items: center; padding: 8px 16px; }
.infoHeader h2 { font-size: var(--font-size-body); font-weight: 600; }
.infoBody { min-height: 0; overflow-y: auto; padding: 20px; scrollbar-width: thin; scrollbar-color: var(--scrollbar-thumb) transparent; }
.infoSection + .infoSection { margin-top: 24px; padding-top: 24px; border-top: 1px solid var(--border-subtle); }
.infoSection h3 { margin-bottom: 12px; color: var(--fg-default); font-size: var(--font-size-body); font-weight: 500; }
.statusRow { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 16px; color: var(--fg-subtle); font-size: var(--font-size-label); }
.statusControls { display: flex; align-items: center; gap: 12px; }
.stateNote { margin-top: 12px; border-radius: 8px; padding: 12px; background: var(--surface-raised); color: var(--fg-subtle); font-size: var(--font-size-label); line-height: 20px; }
.paragraph { color: var(--fg-muted); font-size: var(--font-size-body); line-height: 22px; overflow-wrap: anywhere; }
.breakValue { overflow-wrap: anywhere; }
@media (min-width: 1600px) { .infoPanel { width: 400px; } }
@media (max-width: 1100px) { .infoPanel { width: 320px; } }
@media (max-width: 900px) { .infoPanel { display: none; } }
@media (max-width: 600px) {
  .name { gap: 8px; }
  .readOnly { display: none; }
  .topActions { grid-column: 1 / -1; justify-content: flex-end; }
  .flow { min-width: 360px; padding: 24px 12px 96px; }
  .fields > div { grid-template-columns: 96px minmax(0, 1fr); gap: 12px; }
  .summaryRow { grid-template-columns: 24px 80px minmax(0, 1fr); }
  .windowRow { grid-template-columns: 80px minmax(0, 1fr) minmax(0, 1fr); }
}

"use client";
import { useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { DropdownContent, DropdownMenu, DropdownTrigger } from "@ui/dropdown";
import { MenuItem } from "@ui/menu-item";
import { PageActions, PageBody, PageContent, PageContentHeader } from "@ui/page-layout";
import { Switch } from "@ui/switch";
import { useIcon } from "@lib/icon-context";
import { PortalContainerProvider } from "@lib/portal-container-context";
import { cn } from "@lib/utils";
import type { GlobalLimit } from "./traffic-types";
import { FlowConnector, WorkflowNode } from "./workflow-node";
import { WorkflowCanvasToolbar } from "./workflow-canvas-toolbar";
import flowStyles from "./rule-workflow.module.css";
import styles from "./limit-detail.module.css";
const nodeIds = ["start", "scope", "windows", "action", "result"];
function actionTitle(limit: GlobalLimit) {
    if (limit.action === "queue")
        return `进入队列，最多等待 ${limit.queueWaitMs} 毫秒`;
    if (limit.action === "reply")
        return "返回固定答复，不再调用模型";
    return "返回 429 TRAFFIC_RATE_LIMITED，并附带 Retry-After";
}
function resultText(limit: GlobalLimit) {
    const windows = limit.windows.map((item) => `每${item.unit} ${item.count} 次（突发 ${item.burst}）`).join("、") || "未配置限额窗口";
    const temporary = limit.temporaryEnabled
        ? `；${limit.temporaryStart.replace("T", " ")} 至 ${limit.temporaryEnd.replace("T", " ")} 临时调整为 ${limit.temporaryWindows.map((item) => `每${item.unit} ${item.count} 次（突发 ${item.burst}）`).join("、")}`
        : "";
    return `${windows}${temporary}；${actionTitle(limit)}。`;
}
function ReadonlyRows({ children }: {
    children: ReactNode;
}) {
    return <dl className={styles.fields}>{children}</dl>;
}
function Field({ label, value }: {
    label: string;
    value: ReactNode;
}) {
    return <div><dt>{label}</dt><dd>{value}</dd></div>;
}
function LimitInfo({ limit, onToggle }: {
    limit: GlobalLimit;
    onToggle: () => void;
}) {
    return <aside className={styles.infoPanel} aria-label="限额信息">
    <header className={styles.infoHeader}><h2>限额信息</h2></header>
    <div className={styles.infoBody}>
      <section className={styles.infoSection}>
        <ReadonlyRows>
          <Field label="限额名称" value={limit.name || "未命名限额"}/>
          <Field label="限额 ID" value={<span className={styles.breakValue}>{limit.code}</span>}/>
          <Field label="顺序号" value={limit.order}/>
        </ReadonlyRows>
        <div className={styles.statusRow}><span>当前状态</span><span className={styles.statusControls}><Badge color={limit.enabled ? "green" : "red"} size="sm" variant="dot">{limit.enabled ? "已启用" : "已停用"}</Badge><Switch checked={limit.enabled} label="启用限额" onCheckedChange={onToggle}/></span></div>
        <p className={styles.stateNote}>{limit.enabled ? "已参与全局请求计数，命中条件后按下方窗口累计用量。" : "当前不参与请求计数，下方展示的是启用后的配置预期。"}</p>
      </section>
      <section className={styles.infoSection}>
        <h3>生效摘要</h3>
        <p className={styles.paragraph}>{resultText(limit)}</p>
      </section>
      <section className={styles.infoSection}>
        <h3>未达到限额时</h3>
        <p className={styles.paragraph}>请求不受影响，继续执行后续网关路由。</p>
      </section>
    </div>
  </aside>;
}
export function LimitDetailView({ limit, onBack, onDelete, onEdit, onHistory, onToggle }: {
    limit: GlobalLimit;
    onBack: () => void;
    onDelete: () => void;
    onEdit: () => void;
    onHistory: () => void;
    onToggle: () => void;
}) {
    const Close = useIcon("x");
    const Gauge = useIcon("clock");
    const Edit = useIcon("pencil");
    const More = useIcon("ellipsis");
    const Collapse = useIcon("chevron-up");
    const Expand = useIcon("chevron-down");
    const [expanded, setExpanded] = useState(nodeIds);
    const [zoom, setZoom] = useState(100);
    const [portalContainer, setPortalContainer] = useState<HTMLDivElement | null>(null);
    const canvasRef = useRef<HTMLDivElement>(null);
    const configuredConditions = useMemo(() => limit.conditions.filter((item) => item.value.trim()).length, [limit.conditions]);
    const toggle = (id: string) => setExpanded((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
    const overview = () => { setExpanded([]); setZoom(100); canvasRef.current?.scrollTo({ top: 0, left: 0 }); };
    return <PageContent className={cn("relative", styles.page)} ref={setPortalContainer} role="region" aria-label="全局限额详情">
    <PortalContainerProvider value={portalContainer}>
      <PageContentHeader>
        <Button aria-label="返回全局限额" iconOnly onClick={onBack} type="button" variant="tertiary"><Close aria-hidden/></Button>
        <div className={styles.name}><h1 title={limit.name || "未命名限额"}>{limit.name || "未命名限额"}</h1><Badge color={limit.enabled ? "green" : "red"} size="sm" variant="strong">{limit.enabled ? "已启用" : "已停用"}</Badge><span className={styles.readOnly}>只读</span></div>
        <PageActions className={styles.topActions}>
          <Button leadingIcon={Edit} onClick={onEdit} size="md" variant="primary">编辑限额</Button>
          <DropdownMenu><DropdownTrigger render={<Button aria-label="更多限额操作" iconOnly size="md" variant="ghost"><More /></Button>}/><DropdownContent align="end" className="w-40"><MenuItem index={0} label="修改记录" onSelect={onHistory}/><MenuItem className="text-fg-danger" index={1} label="删除限额" onSelect={onDelete}/></DropdownContent></DropdownMenu>
        </PageActions>
      </PageContentHeader>
      <PageBody className="flex max-w-none gap-2 overflow-hidden bg-surface-raised !p-2 [background-image:radial-gradient(var(--border)_1px,transparent_1px)] [background-position:center] [background-size:22px_22px]">
        <section className={flowStyles.canvasPanel} aria-label="全局限额详情流程">
          <header className={flowStyles.toolbar}><div className={flowStyles.toolbarTitle}><Gauge aria-hidden className="size-4 text-fg-subtle"/><strong>限额流程</strong><span className={flowStyles.toolbarHint}>从计数对象到超限结果，看清限额如何生效</span></div><Button leadingIcon={expanded.length ? Collapse : Expand} onClick={() => setExpanded(expanded.length ? [] : nodeIds)} size="sm" variant="ghost">{expanded.length ? "收起节点" : "展开节点"}</Button></header>
          <div className={`${flowStyles.canvasFrame} relative flex min-h-0 flex-1 flex-col`}>
            <div aria-label="只读限额流程画布，可横向和纵向滚动" className={flowStyles.canvas} ref={canvasRef} role="region" tabIndex={0}>
              <div className={cn(flowStyles.flow, styles.flow)} style={{ zoom: zoom / 100 } as CSSProperties}>
                <WorkflowNode description={`${limit.limitType} · ${limit.dimension}`} expanded={expanded.includes("start")} footer={<>节点输出 <code>request_count</code></>} icon="globe" id="start" onToggle={() => toggle("start")} title="请求计数入口">
                  <ReadonlyRows><Field label="限制类型" value={limit.limitType}/><Field label="计数维度" value={limit.dimension}/></ReadonlyRows>
                </WorkflowNode>
                <FlowConnector><span>确定计数对象</span></FlowConnector>
                <WorkflowNode description={`${limit.dimension} · ${limit.conditions.length} 个匹配条件`} expanded={expanded.includes("scope")} footer={<>节点输出 <code>quota_key</code><span className="ml-auto">{configuredConditions}/{limit.conditions.length} 已配置</span></>} icon="users" id="scope" onToggle={() => toggle("scope")} title="计数对象" tone="purple">
                  <div className={styles.sectionHeading}><span>本限额的匹配条件</span><Badge color="purple" size="sm">{limit.conditionLogic === "and" ? "全部条件（AND）" : "任一条件（OR）"}</Badge></div>
                  <div className={styles.rowList}>{limit.conditions.map((condition, index) => <div className={styles.summaryRow} key={condition.id}>{index ? <span className={styles.logic}>{limit.conditionLogic === "and" ? "且" : "或"}</span> : <span aria-hidden/>}<strong>{condition.field}</strong><span>{condition.operator} {condition.value || "未填写匹配值"}</span></div>)}</div>
                </WorkflowNode>
                <FlowConnector><span>按窗口累计用量</span></FlowConnector>
                <WorkflowNode description={limit.windows.map((item) => `每${item.unit} ${item.count} 次`).join(" · ")} expanded={expanded.includes("windows")} footer={<>节点输出 <code>quota_exceeded: boolean</code><span className="ml-auto">{limit.windows.length} 个窗口</span></>} icon="clock" id="windows" onToggle={() => toggle("windows")} title="限额窗口" tone="purple">
                  <div className={styles.rowList}>{limit.windows.map((item) => <div className={styles.windowRow} key={item.id}><strong>每{item.unit}</strong><span>最多 {item.count} 次</span><span>突发 {item.burst} 次</span></div>)}</div>
                  <div className={cn(styles.temporary, !limit.temporaryEnabled && styles.temporaryOff)}><div><strong>临时阈值</strong><span>{limit.temporaryEnabled ? `${limit.temporaryStart.replace("T", " ")} 至 ${limit.temporaryEnd.replace("T", " ")}` : "未启用"}</span></div>{limit.temporaryEnabled ? <p>{limit.temporaryWindows.map((item) => `每${item.unit} ${item.count} 次（突发 ${item.burst}）`).join("、")}</p> : null}</div>
                </WorkflowNode>
                <FlowConnector><span>超限时执行</span></FlowConnector>
                <WorkflowNode description={actionTitle(limit)} expanded={expanded.includes("action")} footer={<>执行条件 <code>quota_exceeded = true</code></>} icon="shield" id="action" onToggle={() => toggle("action")} title="超限处置" tone="amber">
                  <ReadonlyRows><Field label="处置方式" value={actionTitle(limit)}/>{limit.action === "queue" ? <><Field label="队列容量" value={`${limit.queueSize} 个请求`}/><Field label="最长等待" value={`${limit.queueWaitMs} 毫秒`}/></> : null}{limit.action === "reply" ? <><Field label="固定答复" value={limit.replyContent}/><Field label="原因代码" value={limit.reasonCode || "—"}/></> : null}</ReadonlyRows>
                </WorkflowNode>
                <FlowConnector />
                <WorkflowNode description={resultText(limit)} expanded={expanded.includes("result")} footer={<>节点输出 <code>gateway_response</code></>} icon="check-square" id="result" onToggle={() => toggle("result")} title="处理结果" tone="green"><p className={styles.result}>{resultText(limit)}</p><p className={styles.help}>未达到限额时，请求不受影响，继续执行后续网关路由。</p></WorkflowNode>
              </div>
            </div>
            <WorkflowCanvasToolbar ariaLabel="限额详情画布缩放" className="absolute bottom-5 right-5 max-[600px]:bottom-3 max-[600px]:right-3" onOverview={overview} onZoomChange={setZoom} zoom={zoom}/>
          </div>
        </section>
        <LimitInfo limit={limit} onToggle={onToggle}/>
      </PageBody>
    </PortalContainerProvider>
  </PageContent>;
}

"use client";
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type FormEvent, type ReactNode } from "react";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { Checkbox } from "@ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@ui/dialog";
import { Input } from "@ui/input";
import { RadioGroup, RadioGroupItem } from "@ui/radio-group";
import { Select, SelectContent, SelectItem, SelectTrigger } from "@ui/select";
import { TabItem, TabPanel, Tabs, TabsList } from "@ui/tabs";
import { Textarea } from "@ui/textarea";
import { DateTimePicker, instantToZonedDateTime, parseISODateTime } from "@ui/temporal-picker";
import { Tooltip } from "@ui/tooltip";
import { useIcon } from "@lib/icon-context";
import { PortalContainerProvider } from "@lib/portal-container-context";
import { cn } from "@lib/utils";
import type { GlobalLimit, LimitAction, LimitCondition, LimitWindow } from "./traffic-types";
import { FlowConnector, WorkflowNode } from "./workflow-node";
import { WorkflowZoomSelect } from "./workflow-zoom-select";
import { useDialogFocus } from "./use-dialog-focus";
import flowStyles from "./rule-workflow.module.css";
import styles from "./limit-workflow.module.css";
import { limitConditionFields, limitDimensions, policySets } from "./gateway-policy-data";
const fieldOptions = [...limitConditionFields];
const operatorOptions = ["等于", "属于", "不等于", "不属于"];
const unitOptions = ["秒", "分钟", "小时"];
const allNodeIds = ["start", "scope", "windows", "action", "result"];
function makeCondition(index: number): LimitCondition {
    return { id: `condition-${Date.now()}-${index}`, field: "策略集", operator: "等于", value: index === 0 ? "model-gateway" : "" };
}
function makeWindow(index: number): LimitWindow {
    return { id: `window-${Date.now()}-${index}`, unit: index === 0 ? "秒" : "分钟", count: 1, burst: 1 };
}
export function createDefaultLimit(): GlobalLimit {
    return {
        id: `limit-${Date.now()}`,
        name: "",
        limitType: "限速（GCRA）",
        dimension: "网关模型密钥",
        conditionLogic: "and",
        conditions: [makeCondition(0)],
        windows: [{ ...makeWindow(0), count: 20, burst: 30 }, { ...makeWindow(1), count: 600, burst: 720 }],
        temporaryEnabled: false,
        temporaryWindows: [
            { id: `temporary-window-${Date.now()}-0`, unit: "秒", count: 30, burst: 40 },
            { id: `temporary-window-${Date.now()}-1`, unit: "分钟", count: 900, burst: 1000 },
        ],
        temporaryStart: "2026-09-11T14:38",
        temporaryEnd: "2026-09-11T15:38",
        action: "reject",
        queueSize: 64,
        queueWaitMs: 3000,
        replyContent: "服务繁忙，请稍后重试。",
        reasonCode: "TRAFFIC_RATE_LIMITED",
        enabled: true,
        order: 1000,
        code: `tenant-${Date.now().toString(36)}`,
    };
}
function FieldSelect({ ariaLabel, onChange, options, value }: {
    ariaLabel: string;
    onChange: (value: string) => void;
    options: string[];
    value: string;
}) {
    return (<Select itemDensity="compact" onValueChange={onChange} size="md" value={value}>
      <SelectTrigger aria-label={ariaLabel} className="w-full min-w-0" placeholder="请选择"/>
      <SelectContent>{options.map((option) => <SelectItem key={option} value={option}>{option}</SelectItem>)}</SelectContent>
    </Select>);
}
function FieldLabel({ children, required }: {
    children: ReactNode;
    required?: boolean;
}) {
    return <span className={styles.fieldLabel}>{children}{required ? <span className="text-fg-danger">*</span> : null}</span>;
}
function ConditionRows({ conditions, onChange }: {
    conditions: LimitCondition[];
    onChange: (conditions: LimitCondition[]) => void;
}) {
    const Chevron = useIcon("chevron-down");
    const Plus = useIcon("plus");
    const Trash = useIcon("trash");
    const [editingId, setEditingId] = useState<string | null>(null);
    const update = (id: string, patch: Partial<LimitCondition>) => onChange(conditions.map((item) => item.id === id ? { ...item, ...patch } : item));
    return (<div className={styles.rowGroup}>
      {conditions.map((condition, index) => (<div className={cn(styles.configItem, editingId === condition.id && styles.configItemEditing)} key={condition.id}>
          <div className={styles.configSummary}>
            <button aria-expanded={editingId === condition.id} aria-label={`配置第 ${index + 1} 个匹配条件`} onClick={() => setEditingId(editingId === condition.id ? null : condition.id)} type="button">
              {index > 0 ? <span className={styles.logicBadge}>且</span> : null}
              <span className={styles.summaryTitle}>{condition.field}</span>
              <span className={cn(styles.summaryValue, !condition.value.trim() && styles.summaryPlaceholder)}>{condition.operator} {condition.value.trim() || "未填写匹配值"}</span>
              <Chevron aria-hidden className={cn(styles.summaryChevron, editingId === condition.id && styles.summaryChevronOpen)}/>
            </button>
            <Button aria-label={`删除第 ${index + 1} 个条件`} iconOnly onClick={() => onChange(conditions.filter((item) => item.id !== condition.id))} size="xs" type="button" variant="ghost"><Trash /></Button>
          </div>
          {editingId === condition.id ? <div className={styles.conditionEditor}>
            <label><FieldLabel>条件字段</FieldLabel><FieldSelect ariaLabel={`第 ${index + 1} 个条件字段`} onChange={(field) => update(condition.id, { field })} options={fieldOptions} value={condition.field}/></label>
            <label><FieldLabel>判断方式</FieldLabel><FieldSelect ariaLabel={`第 ${index + 1} 个条件运算符`} onChange={(operator) => update(condition.id, { operator })} options={operatorOptions} value={condition.operator}/></label>
            <label><FieldLabel required>匹配值</FieldLabel>{condition.field === "策略集" ? <FieldSelect ariaLabel={`第 ${index + 1} 个条件值`} onChange={(value) => update(condition.id, { value })} options={[...policySets]} value={condition.value}/> : <Input aria-label={`第 ${index + 1} 个条件值`} onChange={(event) => update(condition.id, { value: event.target.value })} placeholder="请输入稳定 ID 或字段值" size="md" value={condition.value}/>}</label>
          </div> : null}
        </div>))}
      <Button className={styles.addButton} leadingIcon={Plus} onClick={() => { const condition = makeCondition(conditions.length); onChange([...conditions, condition]); setEditingId(condition.id); }} size="sm" type="button" variant="ghost">添加条件</Button>
    </div>);
}
function WindowRows({ windows, onChange }: {
    windows: LimitWindow[];
    onChange: (windows: LimitWindow[]) => void;
}) {
    const Chevron = useIcon("chevron-down");
    const Plus = useIcon("plus");
    const Trash = useIcon("trash");
    const [editingId, setEditingId] = useState<string | null>(null);
    const update = (id: string, patch: Partial<LimitWindow>) => onChange(windows.map((item) => item.id === id ? { ...item, ...patch } : item));
    return (<div className={styles.rowGroup}>
      {windows.map((windowItem, index) => (<div className={cn(styles.configItem, editingId === windowItem.id && styles.configItemEditing)} key={windowItem.id}>
          <div className={styles.configSummary}>
            <button aria-expanded={editingId === windowItem.id} aria-label={`配置第 ${index + 1} 个时间窗口`} onClick={() => setEditingId(editingId === windowItem.id ? null : windowItem.id)} type="button">
              {index > 0 ? <span className={styles.logicBadge}>且</span> : null}
              <span className={styles.summaryTitle}>每{windowItem.unit}</span>
              <span className={styles.summaryValue}>最多 {windowItem.count} 次 · 突发 {windowItem.burst} 次</span>
              <Chevron aria-hidden className={cn(styles.summaryChevron, editingId === windowItem.id && styles.summaryChevronOpen)}/>
            </button>
            <Button aria-label={`删除第 ${index + 1} 个时间窗口`} iconOnly onClick={() => onChange(windows.filter((item) => item.id !== windowItem.id))} size="xs" type="button" variant="ghost"><Trash /></Button>
          </div>
          {editingId === windowItem.id ? <div className={styles.windowEditor}>
