type LimitIssue = {
    nodeId: string;
    message: string;
};
function validateLimit(value: GlobalLimit): LimitIssue[] {
    const issues: LimitIssue[] = [];
    if (!value.conditions.length)
        issues.push({ nodeId: "scope", message: "至少添加一个计数对象条件" });
    else if (value.conditions.some((condition) => !condition.value.trim()))
        issues.push({ nodeId: "scope", message: "请填写每个计数对象条件的匹配值" });
    if (!value.windows.length)
        issues.push({ nodeId: "windows", message: "至少添加一个限额时间窗口" });
    else if (value.windows.length > 3)
        issues.push({ nodeId: "windows", message: "限速最多配置 3 个时间桶" });
    else if (new Set(value.windows.map((windowItem) => windowItem.unit)).size !== value.windows.length)
        issues.push({ nodeId: "windows", message: "每秒、每分钟、每小时各只能配置一个时间桶" });
    if (value.temporaryEnabled && (!value.temporaryStart || !value.temporaryEnd))
        issues.push({ nodeId: "windows", message: "请填写临时阈值的开始和结束时间" });
    else if (value.temporaryEnabled && value.temporaryEnd <= value.temporaryStart)
        issues.push({ nodeId: "windows", message: "临时阈值结束时间应晚于开始时间" });
    else if (value.temporaryEnabled && new Date(value.temporaryEnd).getTime() - new Date(value.temporaryStart).getTime() > 30 * 24 * 60 * 60 * 1000)
        issues.push({ nodeId: "windows", message: "临时抬高最长只能持续 30 天" });
    else if (value.temporaryEnabled && value.temporaryWindows.some((item) => { const base = value.windows.find((windowItem) => windowItem.unit === item.unit); return base && (item.count < base.count || item.burst < base.burst); }))
        issues.push({ nodeId: "windows", message: "临时阈值只能抬高，不能低于基线额度" });
    if (value.action === "queue" && (value.queueSize < 1 || value.queueSize > 512 || value.queueWaitMs < 100 || value.queueWaitMs > 30000))
        issues.push({ nodeId: "action", message: "队列容量须为 1–512，最长等待须为 100–30000 毫秒" });
    if (value.action === "reply" && !value.replyContent.trim())
        issues.push({ nodeId: "action", message: "请填写超限后的固定答复内容" });
    if (value.action === "reply" && (!value.reasonCode.trim() || value.reasonCode.length > 64))
        issues.push({ nodeId: "action", message: "固定答复需要 1–64 字节的原因代码" });
    return issues;
}
function limitResult(value: GlobalLimit) {
    const windows = value.windows.length ? value.windows.map((item) => `每${item.unit} ${item.count} 次（突发 ${item.burst}）`).join("、") : "尚未配置额度";
    const temporary = value.temporaryEnabled
        ? `；${value.temporaryStart.replace("T", " ")} 至 ${value.temporaryEnd.replace("T", " ")} 临时调整为 ${value.temporaryWindows.map((item) => `每${item.unit} ${item.count} 次（突发 ${item.burst}）`).join("、")}`
        : "";
    if (value.action === "queue")
        return `${windows}${temporary}；超限后最多排队 ${value.queueSize} 个请求，每个等待 ${value.queueWaitMs} 毫秒。`;
    if (value.action === "reply")
        return `${windows}${temporary}；超限后直接返回固定答复，不再调用模型。`;
    return `${windows}${temporary}；任一窗口超限后返回 429 TRAFFIC_RATE_LIMITED，并附带 Retry-After。`;
}
