                  </WorkflowNode>
                  <FlowConnector><span>超限时执行</span></FlowConnector>
                  <WorkflowNode description={actionTitle(value.action)} expanded={expanded.includes("action")} footer={<>执行条件 <code>quota_exceeded = true</code></>} icon="shield" id="action" issue={issueFor("action")} onToggle={() => toggle("action")} title="超限处置" tone="amber"><ActionFields onChange={patchValue} value={value}/></WorkflowNode>
                  <FlowConnector />
                  <WorkflowNode description={limitResult(value)} expanded={expanded.includes("result")} footer={<>节点输出 <code>gateway_response</code></>} icon="check-square" id="result" onToggle={() => toggle("result")} title="处理结果" tone="green"><p className={styles.result}>{limitResult(value)}</p><p className={styles.help}>未达到限额时，请求不受影响，继续执行后续网关路由。</p></WorkflowNode>
                </div>
              </div>
              <div className={flowStyles.canvasControls}><WorkflowZoomSelect ariaLabel="限额画布缩放" onChange={setZoom} value={zoom}/><span className="h-4 border-r border-border"/><Button onClick={overview} size="sm" type="button" variant="ghost">流程总览</Button></div>
            </div>
          </section>
          {previewOpen ? <><button aria-label="关闭调试与预览" className={styles.previewBackdrop} onClick={() => setPreviewOpen(false)} tabIndex={-1} type="button"/><aside aria-label="调试与预览" aria-modal={compact || undefined} className={flowStyles.preview} ref={panelRef} role={compact ? "dialog" : "complementary"}><LimitPreview issues={issues} onFocusNode={focusNode} onTabChange={setPreviewTab} tab={previewTab} value={value}/></aside></> : null}
        </div>
      </form>
      {discardOpen ? <DiscardDialog onDiscard={onCancel} onKeep={() => setDiscardOpen(false)}/> : null}
    </PortalContainerProvider>
  </div>;
}

.form {
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.flow {
  min-width: 600px;
  padding: 40px 24px 112px;
}

.fields {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.fields label {
  display: block;
}

.fieldLabel {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 8px;
  color: var(--fg-muted);
  font-size: var(--font-size-label);
  font-weight: 500;
  line-height: 16px;
}

.rowGroup {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-floating);
}

.configItem {
  border-bottom: 1px solid var(--border-subtle);
}

.configItemEditing {
  background: var(--surface-floating);
}

.configSummary {
  display: flex;
  align-items: center;
  padding: 8px;
}

.configSummary > button:first-child {
  display: flex;
  min-width: 0;
  flex: 1;
  cursor: pointer;
  align-items: center;
  gap: 8px;
  border-radius: 6px;
  padding: 4px;
  text-align: left;
}

.configSummary > button:first-child:hover {
  background: var(--surface-raised);
}

.summaryTitle {
  min-width: 88px;
  color: var(--fg-default);
  font-size: var(--font-size-label);
  font-weight: 500;
  line-height: 18px;
}

.summaryValue {
  min-width: 0;
  flex: 1;
  color: var(--fg-muted);
  font-size: var(--font-size-label);
  line-height: 18px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.summaryPlaceholder {
  color: var(--fg-warning);
}

.summaryChevron {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: var(--fg-subtle);
  transition: transform 180ms ease-out;
}

.summaryChevronOpen {
  transform: rotate(180deg);
}

.conditionEditor,
.windowEditor {
  display: grid;
  grid-template-columns: minmax(116px, .9fr) minmax(104px, .7fr) minmax(148px, 1.2fr);
  gap: 12px;
  padding: 16px;
  border-top: 1px solid var(--border);
  background: var(--surface-floating);
}

.windowEditor {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.logicBadge {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--fg-subtle);
  font-size: var(--font-size-label);
}

.addButton {
  margin: 4px 8px;
  color: var(--fg-brand);
}

.conditionHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.conditionHeader .fieldLabel {
  margin-bottom: 0;
}

.conditionHint {
  color: var(--fg-subtle);
  font-size: var(--font-size-label);
  line-height: 20px;
}

.checkboxRow {
  display: flex !important;
  align-items: center;
  gap: 8px;
  color: var(--fg-muted);
  font-size: var(--font-size-label);
}

.temporaryPanel {
  display: flex;
  flex-direction: column;
  gap: 20px;
  border-radius: 12px;
  padding: 16px;
  background: var(--surface-raised);
}

.temporaryRows {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.temporaryRow {
  display: grid;
  grid-template-columns: max-content minmax(72px, 1fr) max-content minmax(72px, 1fr) max-content;
  align-items: center;
  gap: 8px;
  color: var(--fg-default);
  font-size: var(--font-size-label);
  line-height: 20px;
}

.temporaryRow input,
.temporaryDates input {
  background: var(--surface-floating);
}

.temporaryDates {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.actionFields {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.actionOptions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.actionOption {
  display: flex;
  min-width: 0;
  cursor: pointer;
  align-items: flex-start;
  gap: 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px;
  background: var(--surface-floating);
}

.actionOptionSelected {
  border-color: var(--brand);
  background: color-mix(in srgb, var(--brand) 6%, var(--surface-floating));
}

.actionOption span {
  min-width: 0;
}

.actionOption strong,
.actionOption small {
  display: block;
}

.actionOption strong {
  color: var(--fg-default);
  font-size: var(--font-size-label);
  font-weight: 500;
  line-height: 16px;
}

.actionOption small {
  margin-top: 4px;
  color: var(--fg-subtle);
  font-size: var(--font-size-label);
  line-height: 16px;
}

.parameterGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  border-radius: 8px;
  padding: 12px;
  background: var(--surface-raised);
}

.fullField {
  grid-column: 1 / -1;
}

.result {
  color: var(--fg-muted);
  font-size: var(--font-size-body);
  line-height: 22px;
}

.help {
  margin-top: 8px;
  color: var(--fg-subtle);
  font-size: var(--font-size-label);
  line-height: 20px;
}

.previewPanel {
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--surface-floating);
}

.previewTabs {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
}

.previewTabList {
  flex-shrink: 0;
  padding: 0 16px;
}

.previewScroll {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.testBody {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
}

.testBody > p,
.testIssue {
  color: var(--fg-subtle);
  font-size: var(--font-size-label);
  line-height: 20px;
}

.testIssue {
  cursor: pointer;
  color: var(--fg-warning);
  text-align: left;
}

.testResult {
  border-top: 1px solid var(--border-subtle);
  padding: 16px;
}

.testResult h3 {
  margin-bottom: 12px;
  color: var(--fg-default);
  font-size: var(--font-size-label);
  font-weight: 600;
  line-height: 18px;
}

.testResultCard {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  border-radius: 8px;
  padding: 12px;
  background: var(--surface-raised);
}

.testResultCard p {
  color: var(--fg-muted);
  font-size: var(--font-size-label);
  line-height: 20px;
}

.testEmpty {
  display: flex;
  min-height: 144px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px 16px;
  color: var(--fg-subtle);
  text-align: center;
}

.testEmpty svg {
  width: 24px;
  height: 24px;
}

.testEmpty strong {
  color: var(--fg-default);
  font-size: var(--font-size-body);
  font-weight: 500;
}

.testEmpty p {
  max-width: 248px;
  font-size: var(--font-size-label);
  line-height: 20px;
}

.previewHeader {
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px;
}

.previewHeader h2 {
  color: var(--fg-default);
  font-size: var(--font-size-body);
  font-weight: 600;
  line-height: 20px;
}

.previewBody {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 20px 16px;
}

.previewBody section + section {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 1px solid var(--border-subtle);
}

.previewBody h3 {
  color: var(--fg-default);
  font-size: var(--font-size-label);
  font-weight: 600;
  line-height: 18px;
}

.sectionTitle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.issueList {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 12px;
}

.issueList button {
  display: flex;
  width: 100%;
  cursor: pointer;
  align-items: center;
  gap: 8px;
  border: .5px solid var(--border);
  border-radius: 8px;
  background: var(--warning-surface);
  padding: 10px;
  box-shadow: none;
  color: var(--fg-warning);
  text-align: left;
  font-size: var(--font-size-label);
  line-height: 18px;
}

.issueList button:hover {
  background: color-mix(in srgb, var(--warning-surface) 80%, var(--warning-border));
}

.issueList svg,
.successState svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.successState svg {
  margin-top: 1px;
}

.successState {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 12px;
  border-radius: 8px;
  padding: 12px;
  background: var(--success-surface);
  color: var(--fg-success);
  font-size: var(--font-size-label);
  line-height: 18px;
}

.previewFacts {
  margin-top: 8px;
}

.previewFacts div {
  display: grid;
  grid-template-columns: 80px minmax(0, 1fr);
  gap: 12px;
  padding: 9px 0;
  border-bottom: 1px solid var(--border-subtle);
  font-size: var(--font-size-label);
  line-height: 18px;
}

.previewFacts div:last-child {
  border-bottom: 0;
}

.previewFacts dt {
  color: var(--fg-subtle);
}

.previewFacts dd {
  color: var(--fg-default);
  text-align: right;
  overflow-wrap: anywhere;
}

.resultCopy {
  margin-top: 10px;
  border-radius: 8px;
  padding: 12px;
  background: var(--success-surface);
  color: var(--fg-success);
  font-size: var(--font-size-label);
  line-height: 20px;
}

.previewBackdrop {
  display: none;
}

@media (max-width: 900px) {
  .previewBackdrop {
    position: absolute;
    inset: 0;
    z-index: 3;
    display: block;
    cursor: default;
    background: var(--scrim);
  }
}

@media (max-width: 640px) {
  .flow {
    min-width: 560px;
    padding: 24px 24px 100px;
  }

  .conditionEditor,
  .windowEditor {
    grid-template-columns: 1fr;
    padding-right: 16px;
  }

  .conditionHeader {
    align-items: stretch;
    flex-direction: column;
  }

  .actionOptions,
  .parameterGrid,
  .temporaryDates {
    grid-template-columns: 1fr;
  }

  .temporaryRow {
    grid-template-columns: max-content minmax(64px, 1fr) max-content minmax(64px, 1fr) max-content;
  }

  .fullField {
    grid-column: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .issueList button,
  .summaryChevron {
    transition: none;
  }
}

