        return initial.workflow.conditions.map((condition) => ({ ...condition }));
    if (!initial)
        return defaultConditions.map((condition) => ({ ...condition }));
    const items: ConditionItem[] = [];
    if (initial.matcher && initial.matcher !== "全部请求") {
        items.push({
            id: `${initial.id}-path`,
            kind: "path",
            operator: "前缀",
            primary: initial.matcher,
