function actionDetail(action: ActionItem, legacy: boolean): DetailAction {
    const title = action.type === "拒绝这个请求" ? "拒绝本次调用" : action.type;
    const labels = actionParameterLabels[title] ?? [];
    const missing = legacy ? "未记录" : "未设置";
    const fields: DetailField[] = [];
    if (labels[0] || action.primary !== undefined)
        fields.push({ label: labels[0] ?? "附加配置", value: displayValue(action.primary, missing) });
    if (labels[1] || action.secondary !== undefined)
        fields.push({ label: labels[1] ?? "附加值", value: displayValue(action.secondary, missing) });
    let description = fields.map((field) => `${field.label}：${field.value}`).join(" · ");
    if (title === "拒绝本次调用")
        description = "终止当前请求，不再执行后续动作";
    else if (title === directFallbackType)
        description = "使用虚拟模型的兜底模型服务，无需额外配置";
    else if (title === "镜像复制")
