          {actions.map((action, index) => (<ActionRow action={action} canMoveDown={index < actions.length - 1} canMoveUp={index > 0} key={action.id} onChange={onChange} onMove={(direction) => onMove(action.id, direction)} onRemove={() => onRemove(action.id)}/>))}
        </div>) : (<p className="px-4 py-3 text-label text-fg-subtle">此阶段没有动作</p>)}
    </section>);
}
function RuleSectionNav({ modal }: {
