function RuleFormContent({ actions, addPanelOpen, conditions, editingId, name, onActionsChange, onAddPanelOpenChange, onConditionsChange, onEditingIdChange, onNameChange, openGroups, onOpenGroupsChange, }: {
    actions: ActionItem[];
    addPanelOpen: boolean;
    conditions: ConditionItem[];
    editingId: string | null;
    name: string;
    onActionsChange: (actions: ActionItem[]) => void;
    onAddPanelOpenChange: (open: boolean) => void;
    onConditionsChange: (conditions: ConditionItem[]) => void;
    onEditingIdChange: (id: string | null) => void;
    onNameChange: (name: string) => void;
    openGroups: Record<ConditionGroupId, boolean>;
    onOpenGroupsChange: (groups: Record<ConditionGroupId, boolean>) => void;
}) {
    const Plus = useIcon("plus");
    const beforeActions = actions.filter((action) => action.phase === "before");
    const afterActions = actions.filter((action) => action.phase === "after");
    const updateCondition = (next: ConditionItem) => {
        onConditionsChange(conditions.map((condition) => condition.id === next.id ? next : condition));
    };
    const updateAction = (next: ActionItem) => {
        onActionsChange(actions.map((action) => action.id === next.id ? next : action));
    };
    const moveAction = (id: string, direction: -1 | 1) => {
        const current = actions.find((action) => action.id === id);
        if (!current)
            return;
        const phaseActions = actions.filter((action) => action.phase === current.phase);
        const currentPhaseIndex = phaseActions.findIndex((action) => action.id === id);
        const target = phaseActions[currentPhaseIndex + direction];
        if (!target)
            return;
        const currentIndex = actions.findIndex((action) => action.id === current.id);
        const targetIndex = actions.findIndex((action) => action.id === target.id);
        const nextActions = [...actions];
        [nextActions[currentIndex], nextActions[targetIndex]] = [nextActions[targetIndex]!, nextActions[currentIndex]!];
        onActionsChange(nextActions);
    };
    return (<div className="min-w-0 flex-1 space-y-8 p-4 sm:p-6">
      <section id="rule-basic" className="scroll-mt-4">
        <SectionHeading description="使用能说明规则意图的名称，方便后续检索与审计。" required title="基本信息"/>
        <label className="block text-label font-medium">
          规则名称 <span className="text-fg-danger">*</span>
          <Input className="mt-1.5" onChange={(event) => onNameChange(event.target.value)} placeholder="例如：生产环境高优先级流量" required size="md" value={name}/>
        </label>
      </section>

      <section id="rule-conditions" className="scroll-mt-4">
        <SectionHeading count={conditions.length} description="先浏览规则摘要，需要修改时再展开单项。" required title="条件因子"/>
        <div className="mb-3 flex flex-col gap-3 rounded-xl border border-border-subtle bg-surface-raised px-4 py-3 sm:flex-row sm:items-center">
          <div className="min-w-0 flex-1">
            <p className="text-label font-medium">条件关系</p>
            <p className="mt-0.5 text-label text-fg-subtle">请求需要满足这里定义的判断方式</p>
          </div>
          <p className="text-label leading-5 text-fg-subtle">全部条件均需满足（AND）</p>
        </div>
        <div className="space-y-3">
          {conditionGroups.map((group) => (<ConditionGroup conditions={conditions.filter((condition) => definitionMap.get(condition.kind)?.group === group.id)} editingId={editingId} group={group} key={group.id} onConditionChange={updateCondition} onEdit={onEditingIdChange} onOpenChange={() => onOpenGroupsChange({ ...openGroups, [group.id]: !openGroups[group.id] })} onRemove={(id) => {
                onConditionsChange(conditions.filter((condition) => condition.id !== id));
                if (editingId === id)
                    onEditingIdChange(null);
            }} open={openGroups[group.id]}/>))}
          {addPanelOpen ? (<AddConditionPanel onAdd={(kind) => {
                const next = createCondition(kind);
                const group = definitionMap.get(kind)!.group;
                onConditionsChange([...conditions, next]);
                onOpenGroupsChange({ ...openGroups, [group]: true });
                onEditingIdChange(next.id);
                onAddPanelOpenChange(false);
            }} onClose={() => onAddPanelOpenChange(false)}/>) : (<Button leadingIcon={Plus} onClick={() => onAddPanelOpenChange(true)} size="sm" type="button" variant="tertiary">添加条件</Button>)}
        </div>
      </section>

      <section id="rule-actions" className="scroll-mt-4">
        <SectionHeading count={actions.length} description="动作会按列表顺序执行，并按请求生命周期分阶段展示。" required title="处置动作"/>
        <div className="space-y-3">
          <ActionGroup actions={beforeActions} label="转发前执行" onChange={updateAction} onMove={moveAction} onRemove={(id) => onActionsChange(actions.filter((action) => action.id !== id))}/>
          <ActionGroup actions={afterActions} label="收到响应后执行" onChange={updateAction} onMove={moveAction} onRemove={(id) => onActionsChange(actions.filter((action) => action.id !== id))}/>
          <Button leadingIcon={Plus} onClick={() => onActionsChange([
            ...actions,
            { id: newId("action"), type: "拒绝本次调用", phase: "before" },
        ])} size="sm" type="button" variant="tertiary">
            添加动作
          </Button>
        </div>
      </section>

      <section id="rule-exceptions" className="scroll-mt-4">
        <SectionHeading description="未命中和下游不可用时，使用稳定且可预期的兜底行为。" title="异常处理"/>
        <div className="overflow-hidden rounded-xl border border-border bg-surface-floating">
          <div className="grid gap-1 border-b border-border-subtle px-4 py-3 sm:grid-cols-[160px_minmax(0,1fr)] sm:items-center sm:gap-4">
            <span className="text-label font-medium">条件不满足时</span>
            <span className="text-label text-fg-subtle">不做处理，交由下一条规则继续判定</span>
          </div>
          <div className="grid gap-3 bg-surface-floating px-4 py-3 sm:grid-cols-[160px_minmax(0,1fr)] sm:items-center sm:gap-4">
            <span className="text-label font-medium">组件不可用时</span>
            <SelectField ariaLabel="组件不可用时的处理方式" defaultValue="放行" options={["放行", "拒绝本次调用", "转到兜底模型服务"]}/>
          </div>
        </div>
      </section>
    </div>);
}
export function RuleForm({ initial, modal, onCancel, onSave, }: {
    initial?: RuleFormValue;
    modal?: boolean;
    onCancel: () => void;
    onSave: (rule: RuleFormValue) => void;
}) {
    const ArrowLeft = useIcon("arrow-left");
    const [name, setName] = useState(initial?.name ?? "");
    const [conditions, setConditions] = useState<ConditionItem[]>(() => hydrateConditions(initial));
    const [actions, setActions] = useState<ActionItem[]>(() => hydrateActions(initial));
    const [editingId, setEditingId] = useState<string | null>(() => initial ? null : "demo-header");
    const [addPanelOpen, setAddPanelOpen] = useState(false);
    const [openGroups, setOpenGroups] = useState<Record<ConditionGroupId, boolean>>({
        request: true,
        identity: true,
        model: true,
    });
    const canSave = Boolean(name.trim() && conditions.length > 0 && actions.length > 0);
    const submit = (event: FormEvent) => {
        event.preventDefault();
        if (!canSave)
            return;
        const path = conditions.find((condition) => condition.kind === "path" && condition.primary.trim());
        onSave({
            id: initial?.id ?? `rule-${Date.now()}`,
            priority: initial?.priority ?? 1,
            name: name.trim(),
            matcher: path?.primary.trim() || "全部请求",
            enabled: initial?.enabled ?? false,
            conditions: conditions
                .filter((condition) => condition.kind !== "path")
                .map((condition) => `${definitionMap.get(condition.kind)!.label} · ${conditionSummary(condition)}`),
            actions: actions.map((action) => action.type),
        });
    };
    const content = (<form className={cn("flex min-h-0 flex-col bg-surface-floating", modal ? "max-h-[calc(100svh-32px)]" : "min-h-[calc(100svh-56px)]")} onSubmit={submit}>
      <header className="flex min-h-[68px] shrink-0 items-center justify-between gap-4 border-b border-border px-4 py-3 sm:px-6">
        <div className="flex min-w-0 items-center gap-3">
          {!modal ? (<Button aria-label="返回规则详情" iconOnly onClick={onCancel} size="sm" type="button" variant="ghost">
              <ArrowLeft className="size-4"/>
            </Button>) : null}
          <div className="min-w-0">
            <h2 className="truncate text-title font-semibold leading-6" id="rule-form-title">{modal ? "新建规则" : `编辑 ${initial?.name}`}</h2>
            <p className="truncate text-label leading-4 text-fg-subtle">将请求事实组合成一条清晰、可审计的流量规则</p>
          </div>
        </div>
        {!modal ? (<div className="flex shrink-0 gap-2">
            <Button onClick={onCancel} size="sm" type="button" variant="tertiary">取消</Button>
            <Button disabled={!canSave} size="sm" type="submit" variant="neutral">保存</Button>
          </div>) : null}
      </header>
      <div className="flex min-h-0 flex-1 overflow-y-auto scroll-smooth">
        <RuleSectionNav modal={modal}/>
        <RuleFormContent actions={actions} addPanelOpen={addPanelOpen} conditions={conditions} editingId={editingId} name={name} onActionsChange={setActions} onAddPanelOpenChange={setAddPanelOpen} onConditionsChange={setConditions} onEditingIdChange={setEditingId} onNameChange={setName} onOpenGroupsChange={setOpenGroups} openGroups={openGroups}/>
      </div>
      {modal ? (<footer className="flex shrink-0 flex-wrap items-center justify-between gap-3 border-t border-border bg-surface-floating px-4 py-3 sm:px-6">
          <p className="text-label text-fg-subtle">
            已添加 {conditions.length} 个条件 · {actions.length} 个动作
          </p>
          <div className="flex gap-2">
            <Button onClick={onCancel} type="button" variant="tertiary">取消</Button>
            <Button className="px-5" disabled={!canSave} type="submit">保存规则</Button>
          </div>
        </footer>) : null}
    </form>);
    if (!modal)
        return <section className="min-h-[calc(100svh-56px)] overflow-hidden rounded-t-2xl border-[0.5px] border-border bg-surface-floating">{content}</section>;
    return <Dialog onOpenChange={(open) => { if (!open)
        onCancel(); }} open><DialogContent aria-labelledby="rule-form-title" className="!max-w-[960px] overflow-hidden !p-0">{content}</DialogContent></Dialog>;
}

"use client";
import { Fragment } from "react";
import { Badge } from "@ui/badge";
import type { IconName } from "@lib/icon-context";
import type { RuleDetail } from "./rule-detail-model";
import { ruleSkipExplanation } from "./rule-config";
import { FlowConnector, WorkflowConditionBranch, WorkflowNode } from "./workflow-node";
import flowStyles from "./rule-workflow.module.css";
const paragraphClassName = "whitespace-pre-wrap text-body leading-6 [overflow-wrap:anywhere]";
const noteClassName = "mt-3 text-label leading-5 text-fg-subtle [overflow-wrap:anywhere]";
export function DetailFields({ fields }: {
    fields: Array<{
        label: string;
        value: string;
    }>;
}) {
    return <dl className="flex flex-col gap-2">{fields.map((field, index) => (<div className="grid grid-cols-[minmax(80px,28%)_minmax(0,1fr)] items-start gap-3" key={`${field.label}-${index}`}>
      <dt className="text-label leading-5 text-fg-subtle">{field.label}</dt>
      <dd className="min-w-0 whitespace-pre-wrap text-body leading-5 text-fg-default [overflow-wrap:anywhere]">{field.value}</dd>
    </div>))}</dl>;
}
function actionIcon(title: string): IconName {
    if (title === "拒绝本次调用")
        return "circle-x";
    if (title === "敏感内容信息检测")
        return "shield";
    if (title === "应用限额")
        return "clock";
    if (title.includes("头"))
        return "file-text";
    if (title === "复制流量到")
        return "copy";
    return "doc-stepper";
}
export function RuleWorkflowSummary({ detail, enabled, expanded, onToggle }: {
    detail: RuleDetail;
    enabled: boolean;
    expanded: string[];
    onToggle: (id: string) => void;
}) {
    const groups = (["before", "after", null] as const).map((phase) => ({
        phase,
        title: phase === "before" ? "请求转发前" : phase === "after" ? "收到上游响应后" : "执行阶段未记录",
        actions: detail.actions.map((action, index) => ({ action, index })).filter(({ action }) => action.phase === phase),
    })).filter((group) => group.actions.length > 0);
    return <>
    <WorkflowNode id="start" title="请求进入" description="按规则清单中的优先级检查请求" icon="globe" expanded={expanded.includes("start")} onToggle={() => onToggle("start")}>
      <p className={paragraphClassName}>请求进入当前网关后，按「规则清单」中的优先级依次检查规则。</p>
      {!enabled ? <p className={noteClassName}>这条规则当前已停用，不参与请求匹配。</p> : null}
    </WorkflowNode>
    <FlowConnector />
    <WorkflowConditionBranch expanded={expanded.includes("conditions")}>
      <WorkflowNode id="conditions" title="条件判断" description={`${detail.relationLabel} · ${detail.conditions.length} 项`} icon="list-checks" tone="purple" expanded={expanded.includes("conditions")} onToggle={() => onToggle("conditions")} footer={<><span>匹配条件</span><span className="ml-auto">{detail.conditions.length} 项</span></>}>
        <div className="mb-4 flex items-center justify-between gap-3 text-fg-muted max-[600px]:flex-col max-[600px]:items-start max-[600px]:gap-2">
          <span>本规则的匹配条件</span>
          <Badge color={detail.legacy ? "gray" : "purple"} size="sm">{detail.relationLabel}</Badge>
        </div>
        {detail.conditions.length ? <div className="flex flex-col">
          {detail.conditions.map((condition, index) => <section className="border-t border-border-subtle py-4 last:pb-0" key={condition.id} aria-label={condition.label}>
            <h3 className="mb-3 flex items-center gap-2 text-body font-medium leading-5"><span className="grid h-5 min-w-5 place-items-center rounded bg-brand/10 px-1 text-label text-fg-brand">{detail.logic ? index === 0 ? "当" : detail.logic === "and" ? "且" : "或" : index + 1}</span>{condition.label}</h3>
            <DetailFields fields={condition.fields}/>
          </section>)}
        </div> : <p className={noteClassName}>没有保存匹配条件，请进入编辑确认规则范围。</p>}
      </WorkflowNode>
    </WorkflowConditionBranch>

    {groups.map((group) => <section className={`${flowStyles.actionGroup} flex w-full flex-col items-center`} key={group.phase ?? "unknown"} data-expanded={group.actions.some(({ action }) => expanded.includes(action.id))} aria-label={`处置动作：${group.title}`}>
      <h2 className={`${flowStyles.phaseHeading} mb-3 w-[336px] max-w-full text-label font-medium leading-5 text-fg-muted`}>处置动作 · {group.title}</h2>
      {group.actions.map(({ action, index }) => <Fragment key={action.id}>
        <WorkflowNode id={action.id} title={action.title} description={action.description} icon={actionIcon(action.title)} tone="purple" expanded={expanded.includes(action.id)} onToggle={() => onToggle(action.id)} footer={<><span>执行顺序 {index + 1} / {detail.actions.length}</span><span className="ml-auto">{group.title}</span></>}>
          {action.fields.length ? <DetailFields fields={action.fields}/> : <p className={paragraphClassName}>{action.description}</p>}
          {action.unreachable ? <p className="mt-3 text-label leading-5 text-fg-warning">前序动作已拒绝请求，本动作不再执行。</p> : null}
        </WorkflowNode>
        <FlowConnector />
      </Fragment>)}
    </section>)}
    {!detail.actions.length ? <p className="mb-8 w-[var(--expanded-node-width)] max-w-full text-center text-label text-fg-subtle">没有保存处置动作</p> : null}

    <WorkflowNode id="result" title="处理结果" description={detail.resultSummary} icon="check-square" tone="green" expanded={expanded.includes("result")} onToggle={() => onToggle("result")}>
      <p className="mb-2 text-label leading-5 text-fg-success">{enabled ? "命中后的配置预期" : "启用且命中后的配置预期"}</p>
      <p className={paragraphClassName}>{detail.result}</p>
      <p className={noteClassName}>条件不满足时，{ruleSkipExplanation}。</p>
    </WorkflowNode>

    <div className="mt-8 flex w-full max-w-[var(--expanded-node-width)] flex-col items-center border-t border-dashed border-border pt-6">
      <WorkflowNode id="fallback" title="异常处理" description={`组件不可用时：${detail.fallback}`} icon="shield" tone="amber" expanded={expanded.includes("fallback")} onToggle={() => onToggle("fallback")}>
        <DetailFields fields={[{ label: "组件不可用时", value: detail.fallback }]}/>
        <p className={noteClassName}>{detail.legacy ? "历史规则未保存异常策略，编辑并保存后可查看完整配置。" : "仅在执行组件不可用时触发；内容检测命中或触发限额时，按对应动作的配置处理。"}</p>
      </WorkflowNode>
    </div>
  </>;
}

