@media (max-width: 900px) { .preview { position: absolute; top: 72px; bottom: 8px; right: 8px; z-index: 4; box-shadow: var(--shadow-floating); } }
@media (max-width: 600px) {
  .topbar { height: 108px; display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-rows: 32px 40px; padding: 12px; gap: 8px; }
