    onKeep: () => void;
    onDiscard: () => void;
}) {
    return <Dialog onOpenChange={(open) => { if (!open)
        onKeep(); }} open><DialogContent size="sm"><DialogHeader><DialogTitle>退出规则编辑？</DialogTitle><DialogDescription>本次修改尚未保存，退出后将丢失这些修改。</DialogDescription></DialogHeader><DialogFooter><Button onClick={onKeep} variant="tertiary">继续编辑</Button><Button onClick={onDiscard} variant="destructive">放弃修改</Button></DialogFooter></DialogContent></Dialog>;
}
export function RuleWorkflow({ initial, onSave, onCancel }: {
