export function validateWorkflow(draft: RuleWorkflowDraft): WorkflowIssue[] {
    const issues: WorkflowIssue[] = [];
    const add = (nodeId: string, message: string) => issues.push({ nodeId, message });
    if (!draft.name.trim())
        add("start", "请填写规则名称");
    if (draft.logic !== "and")
        add("conditions", "当前仅支持全部条件（AND）");
    if (!draft.conditions.length)
        add("conditions", "请至少添加一个条件");
    const conditionIds = new Set<string>();
    const equalities = new Map<string, string>();
    for (const condition of draft.conditions) {
        const definition = definitionMap.get(condition.kind);
        if (!condition.id || conditionIds.has(condition.id))
            add("conditions", "条件标识缺失或重复，请重新添加该条件");
        conditionIds.add(condition.id);
        if (!definition) {
            add("conditions", "存在不支持的条件类型");
            continue;
        }
        if (condition.kind === "traffic-label") {
            add("conditions", "流量标签是只读遗留条件，新规则不能创建或修改");
            continue;
        }
        if (!conditionComplete(condition)) {
            add("conditions", `请完成${definition.label}的配置，并选择有效运算符`);
            continue;
        }
        if (definition.primaryOptions && !definition.primaryOptions.includes(condition.primary))
            add("conditions", `${definition.label}的选项无效，请重新选择`);
        if (definition.secondaryOptions && !definition.secondaryOptions.includes(condition.secondary ?? ""))
            add("conditions", `${definition.label}的${definition.secondaryLabel}无效`);
        if (condition.kind === "path" && condition.operator !== "正则" && !condition.primary.startsWith("/"))
            add("conditions", "非正则请求路径必须以 / 开头");
        if (condition.kind === "header" && (!headerName.test(condition.primary) || condition.primary !== condition.primary.toLowerCase() || condition.primary.length > 64))
            add("conditions", "请求头名称仅支持小写字母、数字和连字符，且不能超过 64 字节");
        if (condition.kind === "cidr" && !cidrRange(condition.primary))
            add("conditions", condition.primary.includes(":") ? "当前预览仅支持 IPv4 CIDR，不支持 IPv6 网段" : "请输入有效的 IPv4 CIDR，例如 10.0.0.0/8");
        if (condition.kind === "period") {
            if (!periodRange(condition.primary))
                add("conditions", "时段须使用 HH:mm–HH:mm，起止时间不能相同；支持跨午夜");
            if (!validTimezone(condition.secondary ?? ""))
                add("conditions", "请选择有效时区");
        }
        if (draft.logic === "and" && condition.operator === "等于") {
            const keyed = ["header", "query", "cookie", "traffic-label"].includes(condition.kind);
            const key = `${condition.kind}:${keyed ? condition.kind === "header" ? condition.primary.toLowerCase() : condition.primary : ""}`;
            const value = keyed ? condition.secondary ?? "" : condition.primary;
            if (equalities.has(key) && equalities.get(key) !== value)
                add("conditions", `${definition.label}存在互相冲突的相等条件，AND 关系无法命中`);
            equalities.set(key, value);
        }
    }
    if (!draft.actions.length)
        add("actions", "请至少添加一个处置动作");
    const actionIds = new Set<string>();
    let route: ActionItem | undefined;
    let seenAfter = false;
    const headers = new Map<string, string>();
    for (const action of draft.actions) {
        const id = action.id || "actions";
        if (!action.id || actionIds.has(action.id) || ["start", "conditions", "actions", "fallback", "result"].includes(action.id))
            add(id, "动作标识缺失、重复或与系统节点冲突");
        actionIds.add(action.id);
        if (!actionTypes.includes(action.type)) {
            add(id, "请选择支持的动作类型");
            continue;
        }
        const phase = afterActionTypes.has(action.type) ? "after" : "before";
        if (action.phase !== phase)
            add(id, `${action.type}必须在${phase === "before" ? "转发前" : "收到响应后"}执行`);
        if (seenAfter && phase === "before")
            add(id, "转发前动作不能放在响应后动作之后，请调整顺序");
        seenAfter ||= phase === "after";
        if (primaryOptions[action.type] && !primaryOptions[action.type]!.includes(action.primary ?? ""))
            add(id, `请为${action.type}选择有效的${isRoute(action) || action.type === "镜像复制" ? "目标" : "配置"}`);
        if (secondaryOptions[action.type] && !secondaryOptions[action.type]!.includes(action.secondary ?? ""))
            add(id, `请选择${action.type}的处理方式`);
        if (action.type === "拒绝本次调用" && (!action.primary?.trim() || action.primary.length > 64))
            add(id, "请填写 1–64 字节的原因代码");
        if (action.type === "转发到" && !["weightedHash", "weightedRoundRobin"].includes(action.secondary ?? ""))
            add(id, "请选择 weightedHash 或 weightedRoundRobin 分流策略");
        if (["改写请求字段", "改写请求正文", "改写响应字段"].includes(action.type) && (!action.secondary?.startsWith("/") || action.secondary.length > 160))
            add(id, "JSON 指针必须以 / 开头且不超过 160 字节");
        if (action.type === "挂载插件" && !action.primary?.trim())
            add(id, "请填写本租户的插件绑定 ID");
        if (action.type === "状态码映射" && (!/^\d{3}(,\d{3})*$/.test(action.primary ?? "") || !/^\d{3}$/.test(action.secondary ?? "")))
            add(id, "请填写合法的上游状态码列表和返回状态码");
        if (action.type === "镜像复制" && (!/^\d{1,3}%$/.test(action.secondary ?? "") || Number(action.secondary?.replace("%", "")) < 1 || Number(action.secondary?.replace("%", "")) > 100))
            add(id, "镜像采样比例必须为 1–100%");
        if (action.type === "跳过意图识别" && draft.conditions.some((condition) => !["path", "declared-model", "model-service"].includes(condition.kind)))
            add(id, "关闭意图识别时只允许请求路径、客户端声明的模型名和模型服务条件");
        if (action.type === "改写请求头" || action.type === "改写响应头") {
            if (!headerName.test(action.primary ?? ""))
                add(id, "请填写有效的 Header 名称");
            if (!action.secondary?.trim() || /[\r\n]/.test(action.secondary))
                add(id, "请填写 Header 值，且不能包含换行符");
            const key = `${phase}:${action.primary?.toLowerCase()}`;
            if (headers.has(key) && headers.get(key) !== action.secondary)
                add(id, "同一阶段重复改写同一 Header 且值不同，请合并配置");
