export function workflowSampleHint(condition: ConditionItem): string {
    if (condition.kind === "period")
        return `HH:mm（${condition.secondary || "配置时区"}）或含时区的 ISO 时间`;
    if (condition.kind === "cidr")
        return "客户端 IPv4 地址，例如 10.0.0.1";
    if (condition.kind === "caller" || condition.kind === "capability")
        return condition.primary || "稳定对象 ID";
    if (["header", "query", "cookie"].includes(condition.kind))
        return `${condition.primary || "该字段"} 的实际值`;
    return condition.kind === "path" ? "实际请求路径，例如 /v1/chat/completions" : "该条件的实际值";
