export function createWorkflowSamples(draft: RuleWorkflowDraft): Record<string, string> {
    return Object.fromEntries(draft.conditions.map((condition) => {
        let sample = condition.primary;
        if (["header", "query", "cookie"].includes(condition.kind))
            sample = condition.secondary ?? "存在";
        if (condition.kind === "caller" || condition.kind === "capability")
            sample = condition.primary;
        if (condition.kind === "period")
            sample = condition.primary.slice(0, 5);
        if (condition.kind === "cidr")
            sample = condition.primary.split("/")[0] ?? "";
        if (condition.operator === "正则")
            sample = sample.replace(/\^|\$|\\/g, "");
        return [condition.id, sample];
    }));
}
function compare(actual: string, expected: string, operator: string): boolean {
    switch (operator) {
        case "等于":
        case "属于": return actual === expected;
        case "不等于":
        case "不属于": return actual !== expected;
        case "包含": return actual.includes(expected);
        case "前缀": return actual.startsWith(expected);
        case "正则": try {
            return new RegExp(expected).test(actual);
        }
        catch {
            return false;
        }
        default: return false;
    }
}
function evaluateCondition(condition: ConditionItem, samples: Record<string, string>): {
