                {check.matched ? <Check aria-hidden className="mt-1 size-4 shrink-0 text-fg-success"/> : <Blocked aria-hidden className="mt-1 size-4 shrink-0 text-fg-warning"/>}
                <span className="min-w-0 flex-1">
